import{c as a,Q as t,j as s,m as o}from"./chunks/framework.rWdQudnF.js";const m=JSON.parse('{"title":"云原生架构案例分析","description":"","frontmatter":{"title":"云原生架构案例分析"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/云原生架构设计理论与实践（第二版）/云原生架构案例分析.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/云原生架构设计理论与实践（第二版）/云原生架构案例分析.md","lastUpdated":null}'),r={name:"架构师 在线刷题/51CT0题库 章节练习/云原生架构设计理论与实践（第二版）/云原生架构案例分析.md"};function i(n,l,e,c,u,d){return t(),s("div",null,[...l[0]||(l[0]=[o('<h1 id="云原生架构案例分析" tabindex="-1">云原生架构案例分析 <a class="header-anchor" href="#云原生架构案例分析" aria-label="Permalink to &quot;云原生架构案例分析&quot;">​</a></h1><blockquote><p>共 4 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-某电商业务云原生改造的应用成效-不包括-。" tabindex="-1">Q1. 某电商业务云原生改造的应用成效，不包括（ ）。 <a class="header-anchor" href="#q1-某电商业务云原生改造的应用成效-不包括-。" aria-label="Permalink to &quot;Q1. 某电商业务云原生改造的应用成效，不包括（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 系统韧性提升，通过预案和演练保障大促业务稳定</li><li><strong>B.</strong> 未实现对业务接口、第三方调用等的全方位监控防护</li><li><strong>C.</strong> 利用相关服务精准定位和快速解决问题，保障系统稳定</li><li><strong>D.</strong> 成本优化，如 A CK 容器弹性维护节省服务器成本</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-某快递公司将其核心业务系统从传统数据中心迁移至云原生架构-从几个备选方案经过评估后确定了最终上云方案。下列关于该公司云原生架构方案的做法中-正确的是-。" tabindex="-1">Q2. 某快递公司将其核心业务系统从传统数据中心迁移至云原生架构，从几个备选方案经过评估后确定了最终上云方案。下列关于该公司云原生架构方案的做法中，正确的是（ ）。 <a class="header-anchor" href="#q2-某快递公司将其核心业务系统从传统数据中心迁移至云原生架构-从几个备选方案经过评估后确定了最终上云方案。下列关于该公司云原生架构方案的做法中-正确的是-。" aria-label="Permalink to &quot;Q2. 某快递公司将其核心业务系统从传统数据中心迁移至云原生架构，从几个备选方案经过评估后确定了最终上云方案。下列关于该公司云原生架构方案的做法中，正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 未引入云原生数据库，继续使用原有的 Oracle 数据库，以保证数据迁移零风险</li><li><strong>B.</strong> 基于 VMware 虚拟化平台部署应用，仅将操作系统替换为 Linux，未做容器化改造</li><li><strong>C.</strong> 采用阿里云 ACK（容器服务）进行应用编排，底层使用神龙裸金属服务器，数据层使用云原生数据库</li><li><strong>D.</strong> 为降低运维复杂度，未配置弹性伸缩策略，通过预先购买大量固定资源应对业务高峰</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q3-汽车行业进行数字化转型-关于其业务面临的挑战-说法错误的是-。" tabindex="-1">Q3. 汽车行业进行数字化转型，关于其业务面临的挑战，说法错误的是（ ）。 <a class="header-anchor" href="#q3-汽车行业进行数字化转型-关于其业务面临的挑战-说法错误的是-。" aria-label="Permalink to &quot;Q3. 汽车行业进行数字化转型，关于其业务面临的挑战，说法错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 需同时满足 “五联网” 和 “五联网” 价值重构，面临业务模式和架构挑战</li><li><strong>B.</strong> 汽车销售正从传统模式向以服务为驱动的生态模式转变，需融合新技术</li><li><strong>C.</strong> 无需关注用户全生命周期需求，专注产品销售即可应对转型</li><li><strong>D.</strong> 要融入业务每个角落，用数字技术构建新商业模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q4-某旅行公司云原生改造第一阶段的应用成效-不包括-。" tabindex="-1">Q4. 某旅行公司云原生改造第一阶段的应用成效，不包括（ ）。 <a class="header-anchor" href="#q4-某旅行公司云原生改造第一阶段的应用成效-不包括-。" aria-label="Permalink to &quot;Q4. 某旅行公司云原生改造第一阶段的应用成效，不包括（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 业务承载从独享机器集群切换到共享机器集群，资源复用率提升</li><li><strong>B.</strong> 由于调度算法和自研服务接入，资源使用效率优化，成本降低</li><li><strong>C.</strong> 完全解决了旅游业务淡旺季资源波动问题，无需后续改造</li><li><strong>D.</strong> 部分业务测试环境服务器成本因资源复用等下降</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details>',14)])])}const p=a(r,[["render",i]]);export{m as __pageData,p as default};
